using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? _reportingConfiguration;

    private static ReportingConfiguration GetReportingConfiguration()
    {
        if (_reportingConfiguration is not null)
        {
            return _reportingConfiguration;
        }

        // The evaluator chat client is configured via the EVALUATION_CHAT_ENDPOINT and
        // EVALUATION_CHAT_MODEL environment variables or defaults to the app's own endpoint.
        var chatClient = CreateEvaluatorChatClient();

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
        };

        _reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(
                Path.GetDirectoryName(typeof(EvaluationTests).Assembly.Location)!,
                "eval-reports"),
            evaluators: evaluators,
            chatConfiguration: new ChatConfiguration(chatClient));

        return _reportingConfiguration;
    }

    [TestMethod]
    public async Task AnswerIsRelevant()
    {
        var reportingConfig = GetReportingConfiguration();

        await using var scenarioRun = await reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(AnswerIsRelevant));

        var chatClient = CreateAppChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await scenarioRun.EvaluateAsync(messages, response);

        EvaluationAssert.AllMetricsPassed(scenarioRun);
    }

    [TestMethod]
    public async Task AnswerIsCoherent()
    {
        var reportingConfig = GetReportingConfiguration();

        await using var scenarioRun = await reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(AnswerIsCoherent));

        var chatClient = CreateAppChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in two sentences.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await scenarioRun.EvaluateAsync(messages, response);

        EvaluationAssert.AllMetricsPassed(scenarioRun);
    }

    [TestMethod]
    public async Task MultiTurnConversation()
    {
        var reportingConfig = GetReportingConfiguration();

        await using var scenarioRun = await reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(MultiTurnConversation));

        var chatClient = CreateAppChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What are the three primary colors?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        messages.Add(new ChatMessage(ChatRole.User, "Now name a color you get by mixing two of them."));
        response = await chatClient.GetResponseAsync(messages);

        await scenarioRun.EvaluateAsync(messages, response);

        EvaluationAssert.AllMetricsPassed(scenarioRun);
    }

    /// <summary>
    /// Creates the chat client used by the app under test.
    /// Configure via CHAT_ENDPOINT and CHAT_MODEL environment variables.
    /// </summary>
    private static IChatClient CreateAppChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("CHAT_ENDPOINT")
            ?? throw new InvalidOperationException(
                "Set the CHAT_ENDPOINT environment variable to the Azure OpenAI endpoint URL.");

        var apiKey = Environment.GetEnvironmentVariable("CHAT_API_KEY")
            ?? throw new InvalidOperationException(
                "Set the CHAT_API_KEY environment variable.");

        var model = Environment.GetEnvironmentVariable("CHAT_MODEL") ?? "gpt-4o";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(apiKey))
            .GetChatClient(model)
            .AsIChatClient();
    }

    /// <summary>
    /// Creates the chat client used by evaluators (the "judge" model).
    /// Defaults to the same endpoint/model as the app unless overridden.
    /// </summary>
    private static IChatClient CreateEvaluatorChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("EVALUATION_CHAT_ENDPOINT")
            ?? Environment.GetEnvironmentVariable("CHAT_ENDPOINT")
            ?? throw new InvalidOperationException(
                "Set the CHAT_ENDPOINT or EVALUATION_CHAT_ENDPOINT environment variable.");

        var apiKey = Environment.GetEnvironmentVariable("EVALUATION_CHAT_API_KEY")
            ?? Environment.GetEnvironmentVariable("CHAT_API_KEY")
            ?? throw new InvalidOperationException(
                "Set the CHAT_API_KEY or EVALUATION_CHAT_API_KEY environment variable.");

        var model = Environment.GetEnvironmentVariable("EVALUATION_CHAT_MODEL")
            ?? Environment.GetEnvironmentVariable("CHAT_MODEL")
            ?? "gpt-4o";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(apiKey))
            .GetChatClient(model)
            .AsIChatClient();
    }
}

